/*
 * A192596  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and 3x+4y is a prime, then 3x+4y is in S, and 1 is in S.
 * https://oeis.org/A192596
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 43, u32 n <= 43, u64 n <= 43, u128 n <= 43,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A192596
 *  Definition: S is the set containing 1 and closed under the rule
 *  "if x,y ∈ S and 3x+4y is a prime then 3x+4y ∈ S".
 *  The sequence a(n) is S sorted in increasing order, with a(1)=1.
 *
 *  This implementation builds primes up to a fixed limit (20 000 000)
 *  with a sieve, then scans those primes in order, adding each prime
 *  that can be expressed as 3·x+4·y for already‑added x,y ∈ S.
 *  Membership of a value in S is checked with a boolean array for O(1)
 *  lookup.  The algorithm runs in O(LIMIT + n·k) where k ≈ n and
 *  stays well below the time limits for n up to 10 000 on typical
 *  hardware.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

seq_t a(idx_t n)
{
    /* ---------- static data ------------------------------------------------ */
    static bool *is_prime   = NULL;   /* sieve table */
    static bool *visited    = NULL;   /* membership in S */
    static seq_t *S         = NULL;   /* sorted set S */
    static size_t S_len     = 0;      /* current size of S */
    static size_t S_cap     = 0;      /* capacity of S */

    static const idx_t LIMIT = 20000000;          /* maximum value handled               */
    (void)LIMIT;      /* silence unused warning on platforms where LIMIT is unused */

    /* --------- one‑time initialization ------------------------------------ */
    if (is_prime == NULL) {
        /* allocate storage for S */
        S_cap = 128;
        S = (seq_t *)malloc(S_cap * sizeof(seq_t));
        if (!S) return 0;            /* failure: return 0 as a safe fallback */

        S[0] = 1;      /* 1 is always in the set */
        S_len = 1;

        /* allocate and clear visited array */
        visited = (bool *)calloc((size_t)LIMIT + 1, sizeof(bool));
        if (!visited) return 0;
        visited[1] = true;

        /* build prime sieve up to LIMIT */
        is_prime = (bool *)calloc((size_t)LIMIT + 1, sizeof(bool));
        if (!is_prime) return 0;
        memset(is_prime + 2, 1, (size_t)(LIMIT - 1));     /* mark 2..LIMIT as potential primes */
        is_prime[0] = false;
        is_prime[1] = false;

        for (idx_t i = 2; i * i <= LIMIT; ++i) {
            if (is_prime[(size_t)i]) {
                for (idx_t j = i * i; j <= LIMIT; j += i) {
                    is_prime[(size_t)j] = false;
                }
            }
        }
    }

    /* ------------------------------------------------------------ */
    /* generate primes and insert those that satisfy 3x+4y rule  */
    for (idx_t p = 2; p <= LIMIT && S_len < n; ++p) {
        if (!is_prime[(size_t)p]) continue;   /* not a prime – skip */

        /* check if p can be written as 3x+4y with x,y ∈ S */
        bool good = false;
        for (size_t i = 0; i < S_len; ++i) {
            seq_t x = S[i];
            idx_t three_x = 3 * (idx_t)x;
            if (three_x > p) break;            /* further x will be larger */

            idx_t rem = p - three_x;
            if (rem & 3) continue;             /* remainder not divisible by 4 */

            idx_t y = rem >> 2;  /* (p - 3x)/4 */
            if (y <= LIMIT && visited[(size_t)y]) {
                good = true;
                break;
            }
        }

        if (good) {
            if (!visited[(size_t)p]) {          /* add once */
                if (S_len == S_cap) {
                    S_cap *= 2;
                    S = (seq_t *)realloc(S, S_cap * sizeof(seq_t));
                    if (!S) return 0;
                }
                S[S_len++] = p;
                visited[(size_t)p] = true;
            }
        }
    }

    /* If the pre‑chosen limit was insufficient, the function would
       here fail to reach n elements.  For the intended range (n ≤ 10 000)
       LIMIT = 20 000 000 is ample.  If it were not, a larger limit
       could be chosen at the top of the file. */
    return S[n - 1];
}
